mapper.update:
UPDATE operation_record o SET response_ref=#{commandJson},revision=revision+1,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='DC-02' AND idempotency_key=#{key} AND operation_id=#{operationId}
  AND request_sha256=#{requestHash} AND target_id=#{documentId} AND state='PROCESSING' AND revision=#{operationRevision}

UPDATE operation_record o SET state='COMPLETED',http_status=201,response_ref=#{response},revision=revision+1,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='DC-02' AND idempotency_key=#{key} AND operation_id=#{operationId}
  AND request_sha256=#{requestHash} AND target_id=#{documentId} AND state='PROCESSING' AND revision=#{operationRevision}

UPDATE artifact a SET document_revision=#{documentRevision}
WHERE project_id=#{projectId} AND artifact_id=#{input.bodyArtifactId} AND document_revision IS NULL AND artifact_kind='DOCUMENT_BODY'
  AND sha256=#{input.bodySha256} AND object_key=#{bodyReference.objectKey} AND object_version=#{bodyReference.objectVersion}
  AND dependency_access_set_id=#{accessSetId}

UPDATE document_head d SET current_document_revision=#{documentRevision},status='DRAFT',revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND document_id=#{documentId} AND current_document_revision=#{input.baseRevision}
  AND revision=#{input.expectedRevision} AND status<>'SIGNED'
